function createCommandRegistry() {
  const handlers = new Map;
  return {
    register(command, handler3) {
      handlers.set(command, handler3);
    },
    registerAll(entries) {
      for (const { command, handler: handler3 } of entries) {
        handlers.set(command, handler3);
      }
    },
    deregister(command) {
      handlers.delete(command);
    },
    get(command) {
      return handlers.get(command);
    }
  };
}

