class ByteReader {
  #chunks;
  #pending = Buffer.alloc(0);
  constructor(source) {
    this.#chunks = source[Symbol.asyncIterator]();
  }
  async read(max) {
    if (this.#pending.length === 0) {
      const next = await this.#chunks.next();
      if (next.done)
        return;
      this.#pending = next.value;
    }
    const taken = this.#pending.subarray(0, max);
    this.#pending = this.#pending.subarray(taken.length);
    return taken;
  }
  async exact(count) {
    const parts = [];
    for (let left = count;left > 0; ) {
      const part = await this.read(left);
      if (!part)
        throw new Error("the archive ends inside an entry");
      parts.push(part);
      left -= part.length;
    }
    return Buffer.concat(parts);
  }
  async skip(count) {
    for (let left = count;left > 0; ) {
      const part = await this.read(left);
      if (!part)
        throw new Error("the archive ends inside an entry");
      left -= part.length;
    }
  }
}

