  const widths = table2.headers.map((_, i) => Math.max(...all.map((r) => (r[i] ?? "").length)));
  const line = (r) => `  ${r.map((c, i) => c.padEnd(widths[i] ?? 0)).join("  ")}`.trimEnd();
