// src/output/text/migrate.ts
function planGlyph(status) {
  switch (status) {
    case "current":
      return "\u2713";
    case "ready":
      return "\u26A0";
    default:
      return "\u2717";
  }
}
function formatMigratePlain(result) {
  if (!result || typeof result !== "object")
    return null;
  const plan = result;
  if (typeof plan.status !== "string")
    return null;
  const lines = [`${planGlyph(plan.status)} ${plan.status}`];
  if (plan.configFile?.credentials?.length) {
    lines.push(`    credentials.json: ${plan.configFile.credentials.length} key(s) (${plan.configFile.credentials.join(", ")})`);
  }
  if (plan.taskFiles) {
    const tasks = plan.taskFiles;
    lines.push(`    task files: ${tasks.changed} change, ${tasks.skipped} current, ${tasks.blocked} blocked`);
  }
  if (plan.assetEngineKeys) {
    lines.push(`    asset engine keys: ${plan.assetEngineKeys.changed} change, ${plan.assetEngineKeys.skipped} skipped`);
  }
  if (plan.assetContentRefs) {
    const refs = plan.assetContentRefs;
    lines.push(`    asset content refs: ${refs.refs} in ${refs.changed} file(s) change, ${refs.skipped} skipped, ${refs.shadowed?.length ?? 0} shadowed`);
  }
  if (plan.blockers?.length) {
    lines.push("", "blockers:", ...plan.blockers.map((blocker) => `  - ${blocker}`));
  }
  if (plan.configFile?.notes?.length) {
    lines.push("", "config notes:", ...plan.configFile.notes.map((note) => `  - ${note}`));
  }
  if (plan.assetEngineKeys?.notes?.length) {
    lines.push("", "engine name notes:", ...plan.assetEngineKeys.notes.map((note) => `  - ${note}`));
  }
  if (plan.assetContentRefs?.shadowed?.length) {
    lines.push("", "shadowed refs (another file holds the old spelling as its ref; not rewritten, resolve them by hand):", ...plan.assetContentRefs.shadowed.map((ref) => `  - ${ref.bundleId}: ${ref.from} (now ${ref.to})`));
  }
  if (plan.assetContentRefs?.reconcile?.length) {
    lines.push("", "git reconcile:", ...plan.assetContentRefs.reconcile.map((note) => `  - ${note}`));
  }
  if (plan.backupPath) {
    lines.push("", `backup: ${plan.backupPath}`);
  }
  if (plan.applied !== undefined)
    lines.push(`applied: ${plan.applied}`);
  return lines.join(`
`);
}
